"use client"

import * as React from "react"

import {
  createFrameSource,
  isTiffBytes,
  type FrameDescriptor,
  type FrameSource,
} from "@/lib/image-frame-source"
import {
  ImageViewerErrorBoundary,
  ImageViewerFallback,
} from "@/components/ui/image-viewer-chrome"
import {
  clearImageSourceCacheForTests,
  getImageSource,
  ImageViewerContent,
} from "@/components/ui/image-viewer-content"
import type {
  ImageViewerHandle,
  ImageViewerProps,
} from "@/components/ui/image-viewer-types"

export type {
  ImageFrameOverlayProps,
  ImageViewerHandle,
  ImageViewerProps,
} from "@/components/ui/image-viewer-types"
export type { FrameDescriptor, FrameSource }
export { clearImageSourceCacheForTests, getImageSource }

export const ImageViewer = React.forwardRef<
  ImageViewerHandle,
  ImageViewerProps
>(function ImageViewer(props, ref) {
  const isClient = useIsClient()
  if (!isClient) {
    return <ImageViewerFallback className={props.className} bare={props.bare} />
  }
  return (
    <ImageViewerErrorBoundary className={props.className} resetKey={props.src}>
      <React.Suspense
        fallback={
          <ImageViewerFallback className={props.className} bare={props.bare} />
        }
      >
        <ImageViewerContent {...props} forwardedRef={ref} />
      </React.Suspense>
    </ImageViewerErrorBoundary>
  )
})

export function looksLikeTiff(
  src: string,
  contentType: string | null,
  bytes: ArrayBuffer
): boolean {
  return isTiffBytes(src, contentType, bytes)
}

export function createImageSourceForTests(
  kind: "image" | "tiff",
  frames: readonly { width: number; height: number }[],
  decode: (frameIndex: number) => Promise<ImageBitmap>,
  onDispose?: (reason: Error) => void
): FrameSource {
  return createFrameSource({
    kind: kind === "image" ? "native-image" : "tiff",
    frames: frames.map((frame) => ({
      intrinsicSize: { width: frame.width, height: frame.height },
    })),
    decode,
    maxDecodedFrames: 16,
    onDispose,
  })
}

function useIsClient() {
  return React.useSyncExternalStore(
    () => () => {},
    () => true,
    () => false
  )
}

import type * as React from "react"

export interface ImageFrameOverlayProps {
  /** 1-based frame index (a TIFF page; always 1 for single images). */
  frameNumber: number
  /** Rendered frame size in CSS pixels (post-scale, post-rotation). */
  width: number
  height: number
  scale: number
  rotation: number
}

/**
 * Imperative handle for driving the viewer from outside (e.g. scroll to the
 * source of a hovered field). Obtain it with a `ref` on `<ImageViewer>`.
 */
export interface ImageViewerHandle {
  /**
   * Scroll a frame's normalized area into view. `area` fields are percentages
   * [0, 100] of the rendered frame; only `top` is required. Pass
   * `behavior: "auto"` for an instant jump (e.g. on hover).
   */
  scrollToFrameArea: (
    frameNumber: number,
    area: { top: number; left?: number; width?: number; height?: number },
    options?: ScrollToOptions
  ) => void
  /** The scrolling viewport element, or null before the image loads. */
  getViewportElement: () => HTMLDivElement | null
}

export interface ImageViewerProps {
  /** URL of the image (same-origin or CORS-enabled). PNG/JPEG/WebP/GIF/AVIF or TIFF. */
  src: string
  className?: string
  /** Fixed scale; when omitted the viewer fits frame width to the container. */
  scale?: number
  toolbar?: boolean
  downloadFileName?: string
  /** Render absolutely-positioned overlays (e.g. bbox citations) on each frame. */
  renderFrameOverlay?: (props: ImageFrameOverlayProps) => React.ReactNode
  /** Fired with the 1-based frame nearest the top of the viewport as you scroll. */
  onVisibleFrameChange?: (frameNumber: number) => void
  /** Fired with scroll progress in [0, 1] (for a fine-grained scroll cursor). */
  onScrollProgressChange?: (progress: number) => void
  /** Drop the outer border/rounded/background so the viewer fills its container. */
  bare?: boolean
  /** Rendered as a full-width strip directly below the toolbar (e.g. a legend). */
  header?: React.ReactNode
  /** Rendered as a left rail alongside the scrolling frames (e.g. a page ribbon). */
  aside?: React.ReactNode
}

"use client"

import * as React from "react"

import { type FrameSource } from "@/lib/image-frame-source"
import { normalizeRotation, rotatedSize } from "@/lib/image-geometry"
import {
  imageFrameSourceManager,
  type FrameSourceLease,
} from "@/lib/image-source-cache"
import { cn } from "@/lib/utils"
import { ImageViewerToolbar } from "@/components/ui/image-viewer-chrome"
import { ImageFrame } from "@/components/ui/image-viewer-frame"
import {
  type ImageViewerHandle,
  type ImageViewerProps,
} from "@/components/ui/image-viewer-types"
import { ScrollArea } from "@/components/ui/scroll-area"

const IMAGE_SCROLL_HEADROOM = 48
const IMAGE_VIEWER_HORIZONTAL_PADDING = 32

export function ImageViewerContent({
  src,
  className,
  scale: controlledScale,
  toolbar = true,
  downloadFileName,
  renderFrameOverlay,
  onVisibleFrameChange,
  onScrollProgressChange,
  bare = false,
  header,
  aside,
  forwardedRef,
}: ImageViewerProps & {
  forwardedRef?: React.ForwardedRef<ImageViewerHandle>
}) {
  const source = React.use(getImageSource(src))
  const isScaleControlled = controlledScale !== undefined
  const [uncontrolledScale, setUncontrolledScale] = React.useState<
    number | null
  >(null)
  const [rotation, setRotation] = React.useState(0)
  const [frameListWidth, setFrameListWidth] = React.useState<number | null>(
    null
  )
  const [currentFrameNumber, setCurrentFrameNumber] = React.useState(1)
  const scrollViewportRef = React.useRef<HTMLDivElement | null>(null)
  const lastReportedFrameNumber = React.useRef(0)

  const containerRef = React.useCallback((element: HTMLDivElement | null) => {
    if (!element) return
    setFrameListWidth(element.clientWidth)
    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        setFrameListWidth((entry.target as HTMLElement).clientWidth)
      }
    })
    observer.observe(element)
    return () => observer.disconnect()
  }, [])

  const rotationQuarterTurn = normalizeRotation(rotation)
  const widestFrameWidth = Math.max(
    1,
    ...source.frames.map(
      (frame) => rotatedSize(frame.intrinsicSize, rotationQuarterTurn).width
    )
  )
  const fitWidthScale = frameListWidth
    ? (frameListWidth - IMAGE_VIEWER_HORIZONTAL_PADDING) / widestFrameWidth
    : 1
  const scale =
    controlledScale ?? uncontrolledScale ?? Math.max(0.25, fitWidthScale)
  const frameCount = source.frames.length
  const countLabel =
    source.kind === "tiff"
      ? `Page ${Math.min(currentFrameNumber, frameCount)} of ${frameCount}`
      : `${frameCount} image${frameCount === 1 ? "" : "s"}`

  React.useImperativeHandle(
    forwardedRef,
    () => ({
      scrollToFrameArea: (frameNumber, area, options) => {
        const viewport = scrollViewportRef.current
        const frame = viewport?.querySelector<HTMLElement>(
          `[data-frame-number="${frameNumber}"]`
        )
        if (!viewport || !frame) return
        const frameRect = frame.getBoundingClientRect()
        const viewportRect = viewport.getBoundingClientRect()
        const frameTop = frameRect.top - viewportRect.top + viewport.scrollTop
        const targetTop =
          frameTop + (area.top / 100) * frameRect.height - IMAGE_SCROLL_HEADROOM
        viewport.scrollTo({
          top: Math.max(0, targetTop),
          behavior: "smooth",
          ...options,
        })
      },
      getViewportElement: () => scrollViewportRef.current,
    }),
    []
  )

  const sourceLeaseRef = useFrameSourceLease(src, source)

  const handleScroll = React.useCallback(() => {
    const viewport = scrollViewportRef.current
    if (!viewport) return
    const scrollable = viewport.scrollHeight - viewport.clientHeight
    onScrollProgressChange?.(
      scrollable > 0 ? viewport.scrollTop / scrollable : 0
    )

    const viewportRect = viewport.getBoundingClientRect()
    const marker = viewportRect.top + viewportRect.height * 0.2
    const frames = viewport.querySelectorAll<HTMLElement>("[data-frame-number]")
    let frameNumber = 1
    for (const frame of frames) {
      if (frame.getBoundingClientRect().top <= marker) {
        frameNumber = Number(frame.dataset.frameNumber)
      } else {
        break
      }
    }
    if (frameNumber && frameNumber !== lastReportedFrameNumber.current) {
      lastReportedFrameNumber.current = frameNumber
      setCurrentFrameNumber(frameNumber)
      onVisibleFrameChange?.(frameNumber)
    }
  }, [onScrollProgressChange, onVisibleFrameChange])

  const setViewerScale = React.useCallback(
    (nextScale: number | null) => {
      if (isScaleControlled) return
      setUncontrolledScale(nextScale)
    },
    [isScaleControlled]
  )

  return (
    <div
      ref={sourceLeaseRef}
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="image-viewer"
    >
      {toolbar ? (
        <ImageViewerToolbar
          countLabel={countLabel}
          scale={scale}
          src={src}
          downloadFileName={downloadFileName}
          isScaleControlled={isScaleControlled}
          onZoomOut={() => setViewerScale(clamp(scale / 1.2, 0.25, 5))}
          onZoomIn={() => setViewerScale(clamp(scale * 1.2, 0.25, 5))}
          onFitWidth={() => setViewerScale(null)}
          onRotate={() => setRotation((value) => (value + 90) % 360)}
        />
      ) : null}

      <div className="flex min-h-0 flex-1">
        {aside ? (
          <div data-slot="image-viewer-aside" className="flex-shrink-0">
            {aside}
          </div>
        ) : null}
        <div className="flex min-h-0 min-w-0 flex-1 flex-col">
          {header ? <div data-slot="image-viewer-header">{header}</div> : null}
          <ScrollArea
            className="min-h-0 flex-1"
            viewportRef={scrollViewportRef}
            viewportProps={{ onScroll: handleScroll }}
          >
            <div
              ref={containerRef}
              className="flex flex-col items-center gap-4 p-4"
            >
              {source.frames.map((_, frameIndex) => (
                <ImageFrame
                  key={frameIndex}
                  source={source}
                  frameIndex={frameIndex}
                  scale={scale}
                  rotation={rotationQuarterTurn}
                  renderOverlay={
                    renderFrameOverlay
                      ? ({ frameNumber, frameRect, scale, rotation }) =>
                          renderFrameOverlay({
                            frameNumber,
                            width: frameRect.width,
                            height: frameRect.height,
                            scale,
                            rotation,
                          })
                      : undefined
                  }
                />
              ))}
            </div>
          </ScrollArea>
        </div>
      </div>
    </div>
  )
}

export function getImageSource(src: string): Promise<FrameSource> {
  return imageFrameSourceManager.load(src, createTiffWorker)
}

export function clearImageSourceCacheForTests() {
  imageFrameSourceManager.clear()
}

function useFrameSourceLease(
  src: string,
  source: FrameSource
): React.RefCallback<HTMLDivElement> {
  return React.useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return
      const lease = retainImageSource(src, source)
      return () => lease?.release()
    },
    [src, source]
  )
}

function retainImageSource(
  src: string,
  source: FrameSource
): FrameSourceLease | null {
  return imageFrameSourceManager.retain(src, source)
}

function createTiffWorker() {
  return new Worker(new URL("./image-viewer.worker", import.meta.url), {
    type: "module",
  })
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

"use client"

import * as React from "react"

import { ImageDecodeError, type FrameSource } from "@/lib/image-frame-source"
import {
  frameCssSize,
  frameIndexToNumber,
  type FrameOverlayProps,
  type QuarterTurn,
} from "@/lib/image-geometry"
import { Skeleton } from "@/components/ui/skeleton"

export interface ImageFrameProps {
  source: FrameSource
  frameIndex: number
  scale: number
  rotation: QuarterTurn
  renderOverlay?: (props: FrameOverlayProps) => React.ReactNode
}

export function ImageFrame({
  source,
  frameIndex,
  scale,
  rotation,
  renderOverlay,
}: ImageFrameProps) {
  const [isNearViewport, setIsNearViewport] = React.useState(false)
  const descriptor = source.frames[frameIndex]
  const frameRect = frameCssSize(descriptor.intrinsicSize, scale, rotation)

  const frameRef = React.useCallback((element: HTMLDivElement | null) => {
    if (!element) return
    const root = element.closest<HTMLElement>(
      '[data-slot="scroll-area-viewport"]'
    )
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) setIsNearViewport(entry.isIntersecting)
      },
      { root, rootMargin: "150% 0px" }
    )
    observer.observe(element)
    return () => observer.disconnect()
  }, [])

  const frameNumber = frameIndexToNumber(frameIndex)

  return (
    <div
      ref={frameRef}
      className="relative shadow-sm ring-1 ring-border"
      style={{ width: frameRect.width, height: frameRect.height }}
      data-slot="image-frame"
      data-frame={frameNumber}
      data-frame-number={frameNumber}
    >
      {isNearViewport ? (
        <ImageFrameCanvas
          source={source}
          frameIndex={frameIndex}
          scale={scale}
          rotation={rotation}
        />
      ) : (
        <Skeleton className="absolute inset-0 rounded-none" />
      )}
      {renderOverlay ? (
        <div className="pointer-events-none absolute inset-0">
          {renderOverlay({
            frameNumber,
            frameRect,
            scale,
            rotation,
          })}
        </div>
      ) : null}
    </div>
  )
}

function ImageFrameCanvas({
  source,
  frameIndex,
  scale,
  rotation,
}: {
  source: FrameSource
  frameIndex: number
  scale: number
  rotation: QuarterTurn
}) {
  const descriptor = source.frames[frameIndex]
  const dpr = (typeof window !== "undefined" ? window.devicePixelRatio : 1) || 1
  const frameRect = frameCssSize(descriptor.intrinsicSize, scale, rotation)
  const [drawError, setDrawError] = React.useState<Error | null>(null)

  if (drawError) throw drawError

  const canvasRef = React.useCallback(
    (canvas: HTMLCanvasElement | null) => {
      if (!canvas) return
      const ctx = canvas.getContext("2d")
      if (!ctx) return

      canvas.width = Math.max(1, Math.floor(frameRect.width * dpr))
      canvas.height = Math.max(1, Math.floor(frameRect.height * dpr))

      let cancelled = false
      source
        .acquire(frameIndex)
        .then((bitmap) => {
          if (cancelled) return
          ctx.save()
          ctx.scale(dpr, dpr)
          ctx.translate(frameRect.width / 2, frameRect.height / 2)
          ctx.rotate((rotation * Math.PI) / 180)
          const drawWidth = descriptor.intrinsicSize.width * scale
          const drawHeight = descriptor.intrinsicSize.height * scale
          ctx.imageSmoothingQuality = "high"
          ctx.drawImage(
            bitmap,
            -drawWidth / 2,
            -drawHeight / 2,
            drawWidth,
            drawHeight
          )
          ctx.restore()
        })
        .catch((error) => {
          if (!cancelled) {
            setDrawError(
              error instanceof Error
                ? error
                : new ImageDecodeError("Image decode failed", { cause: error })
            )
          }
        })

      return () => {
        cancelled = true
        source.release(frameIndex)
      }
    },
    [
      descriptor.intrinsicSize.height,
      descriptor.intrinsicSize.width,
      dpr,
      frameIndex,
      frameRect.height,
      frameRect.width,
      rotation,
      scale,
      source,
    ]
  )

  return (
    <canvas
      ref={canvasRef}
      style={{ width: frameRect.width, height: frameRect.height }}
      className="block bg-white"
    />
  )
}

"use client"

import * as React from "react"
import { Download, Maximize, Minus, Plus, RotateCw } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import { Skeleton } from "@/components/ui/skeleton"

export interface ImageViewerToolbarProps {
  countLabel: string
  scale: number
  src: string
  downloadFileName?: string
  isScaleControlled?: boolean
  onZoomOut(): void
  onZoomIn(): void
  onFitWidth(): void
  onRotate(): void
}

export function ImageViewerToolbar({
  countLabel,
  scale,
  src,
  downloadFileName,
  isScaleControlled = false,
  onZoomOut,
  onZoomIn,
  onFitWidth,
  onRotate,
}: ImageViewerToolbarProps) {
  return (
    <div className="flex h-10 flex-shrink-0 items-center gap-1 border-b bg-card px-2">
      <span className="px-1 text-xs text-muted-foreground tabular-nums">
        {countLabel}
      </span>
      <div className="ml-auto flex items-center gap-1">
        <ToolbarIconButton
          label="Zoom out"
          onClick={onZoomOut}
          disabled={isScaleControlled}
        >
          <Minus />
        </ToolbarIconButton>
        <span className="w-12 text-center text-xs text-muted-foreground tabular-nums">
          {Math.round(scale * 100)}%
        </span>
        <ToolbarIconButton
          label="Zoom in"
          onClick={onZoomIn}
          disabled={isScaleControlled}
        >
          <Plus />
        </ToolbarIconButton>
        <ToolbarIconButton
          label="Fit width"
          onClick={onFitWidth}
          disabled={isScaleControlled}
        >
          <Maximize />
        </ToolbarIconButton>
        <ToolbarIconButton label="Rotate" onClick={onRotate}>
          <RotateCw />
        </ToolbarIconButton>
        <Separator orientation="vertical" className="mx-1 h-4" />
        <Button
          variant="ghost"
          size="icon-sm"
          className="size-7"
          aria-label="Download"
          title="Download"
          render={
            <a
              href={src}
              download={downloadFileName}
              target="_blank"
              rel="noreferrer"
            />
          }
        >
          <Download />
        </Button>
      </div>
    </div>
  )
}

export function ImageViewerFallback({
  className,
  bare = false,
}: {
  className?: string
  bare?: boolean
}) {
  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="image-viewer"
    >
      <ImageToolbarSkeleton />
      <div className="min-h-0 flex-1 overflow-auto">
        <div className="flex flex-col items-center p-4">
          <ImageFrameSkeleton />
        </div>
      </div>
    </div>
  )
}

export class ImageViewerErrorBoundary extends React.Component<
  { children: React.ReactNode; className?: string; resetKey?: unknown },
  { error: Error | null }
> {
  state: { error: Error | null } = { error: null }

  componentDidUpdate(prev: { resetKey?: unknown }) {
    if (prev.resetKey !== this.props.resetKey && this.state.error) {
      this.setState({ error: null })
    }
  }

  static getDerivedStateFromError(error: Error) {
    return { error }
  }

  componentDidCatch(error: Error) {
    console.error("ImageViewer failed to render.", error)
  }

  render() {
    if (this.state.error) {
      return (
        <div
          className={cn(
            "flex min-h-64 items-center justify-center rounded-xl border bg-muted/30 p-6 text-center text-sm text-muted-foreground",
            this.props.className
          )}
          data-error-message={this.state.error.message}
          data-slot="image-viewer-error"
        >
          Couldn&apos;t load this image.
        </div>
      )
    }
    return this.props.children
  }
}

function ToolbarIconButton({
  label,
  children,
  ...props
}: React.ComponentProps<typeof Button> & { label: string }) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      aria-label={label}
      title={label}
      {...props}
    >
      {children}
    </Button>
  )
}

function ImageToolbarSkeleton() {
  return (
    <div className="flex h-10 flex-shrink-0 items-center gap-1 border-b bg-card px-2">
      <span className="px-1">
        <Skeleton className="inline-block h-3 w-12 align-middle" />
      </span>
      <div className="ml-auto flex items-center gap-1">
        <ToolbarIconPlaceholder>
          <Minus />
        </ToolbarIconPlaceholder>
        <span className="w-12 text-center">
          <Skeleton className="inline-block h-3 w-8 align-middle" />
        </span>
        <ToolbarIconPlaceholder>
          <Plus />
        </ToolbarIconPlaceholder>
        <ToolbarIconPlaceholder>
          <Maximize />
        </ToolbarIconPlaceholder>
        <ToolbarIconPlaceholder>
          <RotateCw />
        </ToolbarIconPlaceholder>
        <Separator orientation="vertical" className="mx-1 h-4" />
        <ToolbarIconPlaceholder>
          <Download />
        </ToolbarIconPlaceholder>
      </div>
    </div>
  )
}

function ToolbarIconPlaceholder({ children }: { children: React.ReactNode }) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      disabled
      tabIndex={-1}
      aria-hidden
    >
      {children}
    </Button>
  )
}

function ImageFrameSkeleton() {
  return (
    <Skeleton aria-hidden className="w-full" style={{ aspectRatio: "4 / 3" }} />
  )
}

export type QuarterTurn = 0 | 90 | 180 | 270

export interface Size {
  width: number
  height: number
}

export interface NormalizedBox {
  left: number
  top: number
  width: number
  height: number
}

export interface FrameOverlayProps {
  frameNumber: number
  frameRect: Size
  scale: number
  rotation: QuarterTurn
}

export function normalizeRotation(rotation: number): QuarterTurn {
  const normalized = ((rotation % 360) + 360) % 360
  if (normalized === 90 || normalized === 180 || normalized === 270) {
    return normalized
  }
  return 0
}

export function isRotatedSideways(rotation: QuarterTurn): boolean {
  return rotation === 90 || rotation === 270
}

export function rotatedSize(size: Size, rotation: QuarterTurn): Size {
  return isRotatedSideways(rotation)
    ? { width: size.height, height: size.width }
    : size
}

export function frameCssSize(
  intrinsicSize: Size,
  scale: number,
  rotation: QuarterTurn
): Size {
  const size = rotatedSize(intrinsicSize, rotation)
  return {
    width: size.width * scale,
    height: size.height * scale,
  }
}

export function rotateNormalizedBox(
  box: NormalizedBox,
  rotation: QuarterTurn
): NormalizedBox {
  if (rotation === 90) {
    return {
      left: 1 - box.top - box.height,
      top: box.left,
      width: box.height,
      height: box.width,
    }
  }
  if (rotation === 180) {
    return {
      left: 1 - box.left - box.width,
      top: 1 - box.top - box.height,
      width: box.width,
      height: box.height,
    }
  }
  if (rotation === 270) {
    return {
      left: box.top,
      top: 1 - box.left - box.width,
      width: box.height,
      height: box.width,
    }
  }
  return box
}

export function frameNumberToIndex(frameNumber: number): number {
  return Math.max(0, Math.floor(frameNumber) - 1)
}

export function frameIndexToNumber(frameIndex: number): number {
  return frameIndex + 1
}

import type { Size } from "@/lib/image-geometry"

export class ImageLoadError extends Error {
  constructor(message: string, options?: ErrorOptions) {
    super(message, options)
    this.name = "ImageLoadError"
  }
}

export class ImageDecodeError extends Error {
  constructor(message: string, options?: ErrorOptions) {
    super(message, options)
    this.name = "ImageDecodeError"
  }
}

export class ImageSourceDisposedError extends Error {
  constructor(message = "Image source disposed", options?: ErrorOptions) {
    super(message, options)
    this.name = "ImageSourceDisposedError"
  }
}

export class ImageFrameIndexError extends Error {
  constructor(frameIndex: number, frameCount: number) {
    super(
      `Invalid image frame index ${frameIndex}; expected 0-${Math.max(0, frameCount - 1)}`
    )
    this.name = "ImageFrameIndexError"
  }
}

export interface FrameDescriptor {
  intrinsicSize: Size
}

export interface FrameSource {
  kind: "native-image" | "tiff"
  frames: readonly FrameDescriptor[]
  acquire(frameIndex: number): Promise<ImageBitmap>
  release(frameIndex: number): void
  dispose(reason?: Error): void
}

interface BitmapCacheOptions {
  maxDecodedFrames: number
}

export class BitmapCache {
  private readonly bitmaps = new Map<number, ImageBitmap>()
  private readonly pinnedFrameIndexes = new Set<number>()
  private readonly frameRecency: number[] = []

  constructor(private readonly options: BitmapCacheOptions) {}

  get(frameIndex: number): ImageBitmap | undefined {
    const bitmap = this.bitmaps.get(frameIndex)
    if (bitmap) this.touch(frameIndex)
    return bitmap
  }

  set(frameIndex: number, bitmap: ImageBitmap) {
    this.bitmaps.set(frameIndex, bitmap)
    this.touch(frameIndex)
    this.evict()
  }

  pin(frameIndex: number) {
    this.pinnedFrameIndexes.add(frameIndex)
    this.touch(frameIndex)
  }

  unpin(frameIndex: number) {
    this.pinnedFrameIndexes.delete(frameIndex)
    this.evict()
  }

  dispose() {
    for (const bitmap of this.bitmaps.values()) closeBitmap(bitmap)
    this.bitmaps.clear()
    this.pinnedFrameIndexes.clear()
    this.frameRecency.length = 0
  }

  private touch(frameIndex: number) {
    const position = this.frameRecency.indexOf(frameIndex)
    if (position >= 0) this.frameRecency.splice(position, 1)
    this.frameRecency.push(frameIndex)
  }

  private evict() {
    for (const frameIndex of [...this.frameRecency]) {
      if (this.bitmaps.size <= this.options.maxDecodedFrames) break
      if (this.pinnedFrameIndexes.has(frameIndex)) continue
      closeBitmap(this.bitmaps.get(frameIndex))
      this.bitmaps.delete(frameIndex)
      this.frameRecency.splice(this.frameRecency.indexOf(frameIndex), 1)
    }
  }
}

interface CreateFrameSourceOptions {
  kind: FrameSource["kind"]
  frames: readonly FrameDescriptor[]
  decode(frameIndex: number): Promise<ImageBitmap>
  maxDecodedFrames: number
  onDispose?: (reason: Error) => void
}

interface InflightFrameDecode {
  promise: Promise<ImageBitmap>
  reject(error: Error): void
}

export function createFrameSource({
  kind,
  frames,
  decode,
  maxDecodedFrames,
  onDispose,
}: CreateFrameSourceOptions): FrameSource {
  const bitmapCache = new BitmapCache({ maxDecodedFrames })
  const inflightDecodes = new Map<number, InflightFrameDecode>()
  let disposed = false

  return {
    kind,
    frames,
    acquire(frameIndex) {
      if (disposed) return Promise.reject(new ImageSourceDisposedError())
      if (!isValidFrameIndex(frameIndex, frames.length)) {
        return Promise.reject(
          new ImageFrameIndexError(frameIndex, frames.length)
        )
      }
      bitmapCache.pin(frameIndex)
      const bitmap = bitmapCache.get(frameIndex)
      if (bitmap) return Promise.resolve(bitmap)

      let inflight = inflightDecodes.get(frameIndex)
      if (!inflight) {
        let rejectInflight: (error: Error) => void = () => {}
        const promise = new Promise<ImageBitmap>((resolve, reject) => {
          rejectInflight = reject
          decode(frameIndex)
            .then((decodedBitmap) => {
              inflightDecodes.delete(frameIndex)
              if (disposed) {
                closeBitmap(decodedBitmap)
                reject(new ImageSourceDisposedError())
                return
              }
              bitmapCache.set(frameIndex, decodedBitmap)
              resolve(decodedBitmap)
            })
            .catch((error) => {
              inflightDecodes.delete(frameIndex)
              bitmapCache.unpin(frameIndex)
              reject(toImageDecodeError(error))
            })
        })
        inflight = { promise, reject: rejectInflight }
        inflightDecodes.set(frameIndex, inflight)
      }

      return inflight.promise
    },
    release(frameIndex) {
      if (!isValidFrameIndex(frameIndex, frames.length)) return
      if (!disposed) bitmapCache.unpin(frameIndex)
    },
    dispose(reason = new ImageSourceDisposedError()) {
      if (disposed) return
      disposed = true
      bitmapCache.dispose()
      for (const inflight of inflightDecodes.values()) inflight.reject(reason)
      inflightDecodes.clear()
      onDispose?.(reason)
    },
  }
}

export async function createNativeImageFrameSource(
  bytes: ArrayBuffer,
  contentType: string | null,
  maxDecodedFrames: number
): Promise<FrameSource> {
  const blob = new Blob([bytes], { type: contentType ?? "" })
  return createNativeImageFrameSourceFromBlob(blob, maxDecodedFrames)
}

export async function createNativeImageFrameSourceFromBlob(
  blob: Blob,
  maxDecodedFrames: number
): Promise<FrameSource> {
  let probe: ImageBitmap
  try {
    probe = await createImageBitmap(blob)
  } catch (error) {
    throw new ImageDecodeError("Failed to decode image", { cause: error })
  }
  const frames: FrameDescriptor[] = [
    { intrinsicSize: { width: probe.width, height: probe.height } },
  ]
  probe.close()
  return createFrameSource({
    kind: "native-image",
    frames,
    maxDecodedFrames,
    decode: () => createImageBitmap(blob),
  })
}

export function isDeclaredTiff(
  src: string,
  contentType: string | null
): boolean {
  return /\.tiff?($|\?)/i.test(src) || isTiffContentType(contentType)
}

export function isDeclaredNativeImage(
  src: string,
  contentType: string | null
): boolean {
  if (isDeclaredTiff(src, contentType)) return false
  if (!contentType)
    return /\.(png|jpe?g|webp|gif|avif|bmp|ico)($|\?)/i.test(src)
  return /^image\/(png|jpe?g|webp|gif|avif|bmp|x-icon|vnd\.microsoft\.icon)(;|$)/i.test(
    contentType
  )
}

export function isTiffBytes(
  src: string,
  contentType: string | null,
  bytes: ArrayBuffer
): boolean {
  if (isDeclaredTiff(src, contentType)) return true
  const b = new Uint8Array(bytes, 0, Math.min(4, bytes.byteLength))
  return (
    (b[0] === 0x49 && b[1] === 0x49 && b[2] === 0x2a && b[3] === 0x00) ||
    (b[0] === 0x4d && b[1] === 0x4d && b[2] === 0x00 && b[3] === 0x2a)
  )
}

export function closeBitmap(bitmap: ImageBitmap | undefined) {
  try {
    bitmap?.close()
  } catch {
    // Disposal must stay idempotent across browser edges and test doubles.
  }
}

function toImageDecodeError(error: unknown): ImageDecodeError {
  return error instanceof ImageDecodeError
    ? error
    : new ImageDecodeError("Image decode failed", { cause: error })
}

function isValidFrameIndex(frameIndex: number, frameCount: number) {
  return (
    Number.isInteger(frameIndex) && frameIndex >= 0 && frameIndex < frameCount
  )
}

function isTiffContentType(contentType: string | null): boolean {
  return contentType ? /^image\/(tiff|tif)(;|$)/i.test(contentType) : false
}

import {
  createNativeImageFrameSource,
  createNativeImageFrameSourceFromBlob,
  ImageLoadError,
  ImageSourceDisposedError,
  isDeclaredNativeImage,
  isDeclaredTiff,
  isTiffBytes,
  type FrameSource,
} from "@/lib/image-frame-source"
import {
  createTiffFrameSource,
  type TiffWorkerFactory,
} from "@/lib/image-tiff-source"

const DEFAULT_MAX_DECODED_FRAMES = 16
const DEFAULT_UNCLAIMED_SOURCE_TIMEOUT_MS = 30_000
const DEFAULT_RELEASED_SOURCE_TIMEOUT_MS = 0

export interface FrameSourceLease {
  source: FrameSource
  release(): void
}

type FrameSourceEntryState = "loading" | "ready" | "released" | "disposed"

interface FrameSourceEntry {
  src: string
  promise: Promise<FrameSource>
  source?: FrameSource
  leaseCount: number
  state: FrameSourceEntryState
  disposeWhenResolved: boolean
  disposeReason?: Error
  disposeTimer?: ReturnType<typeof setTimeout>
}

interface FrameSourceManagerOptions {
  maxDecodedFrames?: number
  releasedSourceTimeoutMs?: number
  unclaimedSourceTimeoutMs?: number
}

export class FrameSourceManager {
  private readonly entries = new Map<string, FrameSourceEntry>()
  private readonly maxDecodedFrames: number
  private readonly releasedSourceTimeoutMs: number
  private readonly unclaimedSourceTimeoutMs: number

  constructor(options: FrameSourceManagerOptions = {}) {
    this.maxDecodedFrames =
      options.maxDecodedFrames ?? DEFAULT_MAX_DECODED_FRAMES
    this.releasedSourceTimeoutMs =
      options.releasedSourceTimeoutMs ?? DEFAULT_RELEASED_SOURCE_TIMEOUT_MS
    this.unclaimedSourceTimeoutMs =
      options.unclaimedSourceTimeoutMs ?? DEFAULT_UNCLAIMED_SOURCE_TIMEOUT_MS
  }

  load(src: string, createTiffWorker: TiffWorkerFactory): Promise<FrameSource> {
    let entry = this.entries.get(src)
    if (!entry) {
      const newEntry: FrameSourceEntry = {
        src,
        promise: Promise.resolve().then(() =>
          this.createSource(src, createTiffWorker)
        ),
        leaseCount: 0,
        state: "loading",
        disposeWhenResolved: false,
      }
      newEntry.promise = newEntry.promise
        .then((source) => {
          newEntry.source = source
          if (newEntry.disposeWhenResolved) {
            source.dispose(
              newEntry.disposeReason ?? new ImageSourceDisposedError()
            )
            this.entries.delete(src)
            newEntry.state = "disposed"
            throw new ImageLoadError("Image source was disposed before use")
          }
          if (newEntry.leaseCount === 0) {
            newEntry.state = "released"
            this.scheduleDispose(
              newEntry,
              this.unclaimedSourceTimeoutMs,
              new ImageSourceDisposedError()
            )
          } else {
            newEntry.state = "ready"
          }
          return source
        })
        .catch((error) => {
          if (this.entries.get(src) === newEntry) this.entries.delete(src)
          throw error
        })
      entry = newEntry
      this.entries.set(src, entry)
    }
    return entry.promise
  }

  retain(src: string, source: FrameSource): FrameSourceLease | null {
    const entry = this.entries.get(src)
    if (!entry || entry.source !== source || entry.state === "disposed") {
      return null
    }
    this.cancelDispose(entry)
    entry.state = "ready"
    entry.leaseCount += 1
    let released = false
    return {
      source,
      release: () => {
        if (released) return
        released = true
        const current = this.entries.get(src)
        if (!current || current.source !== source) return
        current.leaseCount = Math.max(0, current.leaseCount - 1)
        if (current.leaseCount === 0) {
          current.state = "released"
          this.scheduleDispose(
            current,
            this.releasedSourceTimeoutMs,
            new ImageSourceDisposedError()
          )
        }
      },
    }
  }

  clear() {
    for (const entry of [...this.entries.values()]) {
      this.disposeEntry(entry, new ImageSourceDisposedError())
    }
  }

  private async createSource(
    src: string,
    createTiffWorker: TiffWorkerFactory
  ): Promise<FrameSource> {
    const response = await fetch(src)
    if (!response.ok) {
      throw new ImageLoadError(`Failed to load image: ${response.status}`)
    }
    const contentType = response.headers.get("content-type")

    if (isDeclaredTiff(src, contentType)) {
      return createTiffFrameSource(
        await response.arrayBuffer(),
        createTiffWorker,
        this.maxDecodedFrames
      )
    }

    if (isDeclaredNativeImage(src, contentType)) {
      return createNativeImageFrameSourceFromBlob(
        await response.blob(),
        this.maxDecodedFrames
      )
    }

    const bytes = await response.arrayBuffer()
    if (isTiffBytes(src, contentType, bytes)) {
      return createTiffFrameSource(
        bytes,
        createTiffWorker,
        this.maxDecodedFrames
      )
    }

    return createNativeImageFrameSource(
      bytes,
      contentType,
      this.maxDecodedFrames
    )
  }

  private disposeEntry(entry: FrameSourceEntry, reason: Error) {
    if (entry.state === "disposed") return
    entry.state = "disposed"
    entry.disposeWhenResolved = true
    entry.disposeReason = reason
    this.cancelDispose(entry)
    entry.source?.dispose(reason)
    if (this.entries.get(entry.src) === entry) this.entries.delete(entry.src)
  }

  private scheduleDispose(
    entry: FrameSourceEntry,
    delayMs: number,
    reason: Error
  ) {
    this.cancelDispose(entry)
    entry.disposeReason = reason
    entry.disposeTimer = setTimeout(() => {
      const current = this.entries.get(entry.src)
      if (!current || current !== entry || current.leaseCount > 0) return
      this.disposeEntry(current, reason)
    }, delayMs)
  }

  private cancelDispose(entry: FrameSourceEntry) {
    if (!entry.disposeTimer) return
    clearTimeout(entry.disposeTimer)
    entry.disposeTimer = undefined
  }
}

export const imageFrameSourceManager = new FrameSourceManager()

import {
  closeBitmap,
  createFrameSource,
  ImageDecodeError,
  type FrameDescriptor,
  type FrameSource,
} from "@/lib/image-frame-source"

export class TiffWorkerError extends Error {
  constructor(message: string, options?: ErrorOptions) {
    super(message, options)
    this.name = "TiffWorkerError"
  }
}

export type TiffWorkerRequest =
  | { type: "init"; buffer: ArrayBuffer }
  | { type: "decodeFrame"; requestId: number; frameIndex: number }

export type TiffWorkerResponse =
  | { type: "initOk"; frames: FrameDescriptor[] }
  | { type: "initError"; message: string }
  | { type: "decodeFrameOk"; requestId: number; bitmap: ImageBitmap }
  | { type: "decodeFrameError"; requestId: number; message: string }

export type TiffWorkerFactory = () => Worker

interface PendingDecode {
  resolve(bitmap: ImageBitmap): void
  reject(error: Error): void
}

export class TiffWorkerClient {
  private readonly worker: Worker
  private readonly pendingDecodes = new Map<number, PendingDecode>()
  private initResolve: ((frames: readonly FrameDescriptor[]) => void) | null =
    null
  private initReject: ((error: Error) => void) | null = null
  private nextRequestId = 0
  private disposed = false

  constructor(createWorker: TiffWorkerFactory) {
    this.worker = createWorker()
    this.worker.onmessage = (event: MessageEvent<TiffWorkerResponse>) => {
      this.handleMessage(event.data)
    }
    this.worker.onerror = (event) => {
      this.fail(new TiffWorkerError(event.message || "TIFF worker failed"))
    }
    this.worker.onmessageerror = () => {
      this.fail(new TiffWorkerError("TIFF worker sent an unreadable message"))
    }
  }

  init(buffer: ArrayBuffer): Promise<readonly FrameDescriptor[]> {
    if (this.disposed) {
      return Promise.reject(new TiffWorkerError("TIFF worker disposed"))
    }
    return new Promise((resolve, reject) => {
      this.initResolve = resolve
      this.initReject = reject
      try {
        this.worker.postMessage({ type: "init", buffer }, [buffer])
      } catch (error) {
        this.initResolve = null
        this.initReject = null
        reject(
          new TiffWorkerError("Failed to initialize TIFF worker", {
            cause: error,
          })
        )
      }
    })
  }

  decode(frameIndex: number): Promise<ImageBitmap> {
    if (this.disposed) {
      return Promise.reject(new TiffWorkerError("TIFF worker disposed"))
    }
    return new Promise((resolve, reject) => {
      const requestId = this.nextRequestId++
      this.pendingDecodes.set(requestId, { resolve, reject })
      try {
        this.worker.postMessage({ type: "decodeFrame", requestId, frameIndex })
      } catch (error) {
        this.pendingDecodes.delete(requestId)
        reject(
          new TiffWorkerError("Failed to request TIFF frame decode", {
            cause: error,
          })
        )
      }
    })
  }

  dispose(reason = new TiffWorkerError("TIFF worker disposed")) {
    if (this.disposed) return
    this.disposed = true
    this.rejectInit(reason)
    this.rejectPending(reason)
    this.worker.terminate()
  }

  private handleMessage(message: TiffWorkerResponse) {
    if (message.type === "initOk") {
      this.initResolve?.(message.frames)
      this.initResolve = null
      this.initReject = null
      return
    }
    if (message.type === "initError") {
      this.disposed = true
      this.rejectInit(new TiffWorkerError(message.message))
      this.worker.terminate()
      return
    }
    if (message.type === "decodeFrameOk") {
      const pending = this.pendingDecodes.get(message.requestId)
      this.pendingDecodes.delete(message.requestId)
      if (pending) pending.resolve(message.bitmap)
      else closeBitmap(message.bitmap)
      return
    }
    const pending = this.pendingDecodes.get(message.requestId)
    this.pendingDecodes.delete(message.requestId)
    pending?.reject(new ImageDecodeError(message.message))
  }

  private fail(error: Error) {
    this.disposed = true
    this.rejectInit(error)
    this.rejectPending(error)
    this.worker.terminate()
  }

  private rejectInit(error: Error) {
    this.initReject?.(error)
    this.initResolve = null
    this.initReject = null
  }

  private rejectPending(error: Error) {
    for (const pending of this.pendingDecodes.values()) pending.reject(error)
    this.pendingDecodes.clear()
  }
}

export async function createTiffFrameSource(
  buffer: ArrayBuffer,
  createWorker: TiffWorkerFactory,
  maxDecodedFrames: number
): Promise<FrameSource> {
  const client = new TiffWorkerClient(createWorker)
  const frames = await client.init(buffer)
  return createFrameSource({
    kind: "tiff",
    frames,
    maxDecodedFrames,
    decode: (frameIndex) => client.decode(frameIndex),
    onDispose: (reason) => client.dispose(reason),
  })
}

// Web Worker that owns TIFF decode (UTIF) so it never blocks the UI thread.
// The main thread transfers file bytes in once; the worker parses frame metadata
// up front, decodes requested frames on demand, and transfers ImageBitmaps back.
// @ts-expect-error utif ships no type declarations; typed via the local shape.
import UTIF from "utif"

import type {
  TiffWorkerRequest,
  TiffWorkerResponse,
} from "@/lib/image-tiff-source"

interface Ifd {
  t256?: number[]
  t257?: number[]
  width?: number
  height?: number
  data?: unknown
}

interface Utif {
  decode(buf: ArrayBuffer): Ifd[]
  decodeImage(buf: ArrayBuffer, ifd: Ifd): void
  toRGBA8(ifd: Ifd): Uint8Array
}

const utif = UTIF as Utif
const ctx = self as unknown as Worker

let buffer: ArrayBuffer | null = null
let ifds: Ifd[] = []

ctx.onmessage = async (event: MessageEvent<TiffWorkerRequest>) => {
  const message = event.data

  if (message.type === "init") {
    initialize(message.buffer)
    return
  }

  await decodeFrame(message.requestId, message.frameIndex)
}

function initialize(nextBuffer: ArrayBuffer) {
  try {
    buffer = nextBuffer
    ifds = utif.decode(buffer)
    if (ifds.length === 0) throw new Error("TIFF has no frames")
    post({
      type: "initOk",
      frames: ifds.map((ifd, frameIndex) => {
        const width = frameWidth(ifd)
        const height = frameHeight(ifd)
        if (!width || !height) {
          throw new Error(`TIFF frame ${frameIndex + 1} has no dimensions`)
        }
        return { intrinsicSize: { width, height } }
      }),
    })
  } catch (error) {
    post({ type: "initError", message: errorMessage(error) })
  }
}

async function decodeFrame(requestId: number, frameIndex: number) {
  let didDecode = false
  let ifd: Ifd | undefined
  try {
    if (!buffer) throw new Error("worker not initialized")
    if (frameIndex < 0 || frameIndex >= ifds.length) {
      throw new Error(`TIFF frame ${frameIndex + 1} is out of range`)
    }
    ifd = ifds[frameIndex]
    const width = frameWidth(ifd)
    const height = frameHeight(ifd)
    if (!width || !height) {
      throw new Error(`TIFF frame ${frameIndex + 1} has no dimensions`)
    }

    utif.decodeImage(buffer, ifd)
    didDecode = true
    const rgba = utif.toRGBA8(ifd)
    const image = new ImageData(new Uint8ClampedArray(rgba), width, height)
    const bitmap = await createImageBitmap(image)
    post({ type: "decodeFrameOk", requestId, bitmap }, [bitmap])
  } catch (error) {
    post({
      type: "decodeFrameError",
      requestId,
      message: `TIFF frame ${frameIndex + 1}: ${errorMessage(error)}`,
    })
  } finally {
    if (didDecode && ifd) delete ifd.data
  }
}

function post(message: TiffWorkerResponse, transfer?: Transferable[]): void {
  ctx.postMessage(message, transfer ?? [])
}

function frameWidth(ifd: Ifd): number {
  return ifd.width ?? ifd.t256?.[0] ?? 0
}

function frameHeight(ifd: Ifd): number {
  return ifd.height ?? ifd.t257?.[0] ?? 0
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : "TIFF decode failed"
}
